INSERT OR IGNORE INTO categories(name,slug,description,sort_order) VALUES ('Holocron Archives','holocron-archives','Star Wars / Shared artifact scholarship, holocrons, kyber and ancient records.',25);
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Force abilities: perception, connection and telekinesis','force-abilities-perception','Force perception and telekinesis appear across both traditions. Compare Luke’s training in The Empire Strikes Back with Rey’s developing abilities. Distinguish sensing an event from interpreting its cause. These abilities are fictional.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Force visions, prophecy and the problem of interpretation','force-visions-prophecy','Visions can reveal possible futures but their interpretation remains uncertain. Compare Anakin’s fear of loss with Luke’s concern for his friends. Study how choices can contribute to feared outcomes.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Force traditions beyond Jedi and Sith','force-other-traditions','The Nightsisters, Guardians of the Whills and Bendu illustrate traditions outside the Jedi/Sith binary. Compare The Clone Wars, Rogue One and Rebels; distinguish demonstrated abilities from beliefs.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Comparative philosophy: attachment, passion and freedom','force-comparative-philosophy','Compare Jedi service and restraint with Sith passion and ambition. Distinguish compassion from possessiveness, discipline from suppression, and autonomy from coercion. Discuss freedom that respects others’ agency.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Canon timeline: the Republic, Clone Wars and Imperial rise','history-republic-empire','Study the Republic’s political instability, militarization during the Clone Wars and transformation into the Empire. Compare the prequel films and The Clone Wars. Identify institutional decisions and their consequences.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Canon timeline: rebellion, restoration and the First Order','history-rebellion-restoration','Compare Rogue One, the original trilogy, The Mandalorian and sequel trilogy. Study the challenges of rebuilding institutions after Imperial rule and the emergence of the First Order.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Legends timeline: ancient Sith and the Old Republic','history-legends-old-republic','Legends sources include Tales of the Jedi, Knights of the Old Republic and The Old Republic. Keep their timelines separate from current Canon. Examine how recurring wars shaped both orders.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Holocron Archives: catalog and research protocol','holocron-catalog','Catalog artifacts by name, tradition, continuity, source, history and narrative function. Start with primary stories and the official Databank. Separate evidence from interpretation.',1 FROM categories c CROSS JOIN users u WHERE c.slug='holocron-archives' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Jedi and Sith holocrons: knowledge and access','holocron-jedi-sith','Holocrons preserve fictional teachings and sometimes restrict access. Rebels explores Jedi and Sith holocrons through Ezra and Maul. Discuss responsibility and accountability in preserving knowledge.',0 FROM categories c CROSS JOIN users u WHERE c.slug='holocron-archives' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Kyber crystals: symbolism, color and continuity','holocron-kyber','Compare kyber selection in The Clone Wars with red crystal bleeding in Darth Vader (2017) and purification in Ahsoka. Legends differs. Color alone does not establish personality or rank.',0 FROM categories c CROSS JOIN users u WHERE c.slug='holocron-archives' AND u.username='knightfall' AND u.role='god';